export type ChatFilterResult = { ok: true; text: string } | { ok: false; why: ChatRejectReason | 'empty' | 'long' };

export interface ChatFilterOptions {
    /** A 16-17 ↔ 18+ thread: refuse age and meeting probes too. */
    probes?: boolean;
}

const INVISIBLE_RE =
    /[\u00AD\u034F\u061C\u115F\u1160\u17B4\u17B5\u180E\u200B-\u200F\u202A-\u202E\u2060-\u206F\u3164\uFEFF\uFFA0]/g;
const CONTROL_RE = /[\u0000-\u001F\u007F-\u009F\u2028\u2029]/g;
const SPACES_RE = /[\s\u00A0\u1680\u2000-\u200A\u202F\u205F\u3000]+/g;
const APOSTROPHES_RE = /[\u2018\u2019\u201A\u201B\u2032\u02BC\u00B4`]/g;
const QUOTES_RE = /[\u201C\u201D\u201E\u201F\u2033]/g;
const DASHES_RE = /[\u2010-\u2015\u2212\uFE63\uFF0D]/g;
const REPEAT_RE = /([\uD800-\uDBFF][\uDC00-\uDFFF]|[\s\S])\1{3,}/g;

/**
 * One allowed unit: Latin letters with diacritics (Lithuanian included), digits, basic punctuation, the BMP symbol and
 * dingbat emoji, emoji surrogate pairs (U+1F000–U+1FAFF) and the emoji variation selector.
 */
const ALLOWED_RE = new RegExp(
    '^(?:[A-Za-z0-9\u00C0-\u00D6\u00D8-\u00F6\u00F8-\u024F\u1E00-\u1EFF ' +
        '.,!?\'"()[\\]{}:;\\-_&+/#%*~=<>@$\u20AC\u00A3\u2026\u00B0' +
        '\u2190-\u21FF\u2300-\u23FF\u2600-\u27BF\u2B00-\u2BFF\u2764\uFE0F\u20E3' +
        ']|\uD83C[\uDC00-\uDFFF]|\uD83D[\uDC00-\uDFFF]|\uD83E[\uDC00-\uDFFF])*$'
);

const codePoints = (s: string) => s.replace(/[\uD800-\uDBFF][\uDC00-\uDFFF]/g, '_').length;

/** NFKC, invisible/bidi/control characters out, one line, smart quotes to ASCII, 4+ repeats to 3, trimmed. */
export function normalizeChatText(input: string): string {
    return String(input)
        .normalize('NFKC')
        .replace(/[\r\n\t]+/g, ' ')
        .replace(INVISIBLE_RE, '')
        .replace(CONTROL_RE, '')
        .replace(APOSTROPHES_RE, "'")
        .replace(QUOTES_RE, '"')
        .replace(DASHES_RE, '-')
        .replace(SPACES_RE, ' ')
        .replace(REPEAT_RE, '$1$1$1')
        .replace(/^ +| +$/g, '');
}

