const CHAT_WORD_SET: Readonly<Record<string, true>> = toSet(CHAT_WORDS);
const SOCIAL_SET: Readonly<Record<string, true>> = toSet(SOCIAL_APPS);
const CONTACT_SET: Readonly<Record<string, true>> = toSet(CONTACT_WORDS);

function toSet(words: ReadonlyArray<string>): Record<string, true> {
    const out: Record<string, true> = {};
    for (let i = 0; i < words.length; i += 1) out[words[i]] = true;
    return out;
}

/** The message as words (split on spaces and punctuation, `@`/`$`/`!` kept for leet), lowercased. */
function wordsOf(text: string): string[] {
    return text
        .toLowerCase()
        .split(/[\s.,?:;()[\]{}"'\-_\/&+#%*~=<>\u2026]+/)
        .filter(w => !!w);
}

/** Runs of single-character words joined (`f u c k`, `k y s`), so spacing cannot hide a word. */
function spacedRuns(words: ReadonlyArray<string>): string[] {
    const out: string[] = [];
    let run = '';
    for (let i = 0; i < words.length; i += 1) {
        const folded = foldCatName(words[i]);
        if (folded.length === 1) {
            run += folded;
            continue;
        }
        if (run.length >= 3) out.push(run);
        run = '';
    }
    if (run.length >= 3) out.push(run);
    return out;
}

/** Whitespace-separated tokens, so punctuation inside a token cannot split a word (`fu.ck`, `f*ck`). */
function tokensOf(text: string): string[] {
    return text
        .toLowerCase()
        .split(/\s+/)
        .filter(w => !!w);
}

/** Runs of single characters separated by spaces glued together (`g o o g l e . c o m` -> `google.com`). */
function collapseSpaced(text: string): string {
    return text.replace(
        /(?:^|\s)((?:\S\s+){2,}\S)(?=\s|$)/g,
        (m, run: string) => (m.charAt(0) === ' ' ? ' ' : '') + run.replace(/\s+/g, '')
    );
}

function hasWords(text: string): boolean {
    const words = wordsOf(text);
    const candidates = words.concat(spacedRuns(words), tokensOf(text));
    for (let i = 0; i < candidates.length; i += 1) {
        const w = candidates[i];
        if (isBlockedCatName(w)) return true;
        if (CHAT_WORD_SET[foldCatName(w)]) return true;
    }
    const skeleton = foldCatName(text);
    for (let i = 0; i < CHAT_PHRASES_ANYWHERE.length; i += 1)
        if (skeleton.indexOf(CHAT_PHRASES_ANYWHERE[i]) !== -1) return true;
    return false;
}

function hasEmailOrHandle(text: string): boolean {
    for (let i = 0; i < EMAIL_RES.length; i += 1) if (EMAIL_RES[i].test(text)) return true;
    if (HANDLE_RE.test(text)) return true;
    const words = wordsOf(text).map(foldCatName);
    for (let i = 0; i < words.length; i += 1) if (CONTACT_SET[words[i]]) return true;
    return false;
}

function hasLink(text: string): boolean {
    const collapsed = collapseSpaced(text);
    for (let i = 0; i < LINK_RES.length; i += 1)
        if (LINK_RES[i].test(text) || (collapsed !== text && LINK_RES[i].test(collapsed))) return true;
    // social apps by name, as whole words on the raw lowercase words (leet folding would turn `1g` into `ig`)
    const words = wordsOf(text);
    for (let i = 0; i < words.length; i += 1) {
        const w = words[i].replace(/[^a-z0-9]/g, '');
        if (SOCIAL_SET[w]) return true;
    }
    const joined = words.join('');
    if (/discord|snapchat|instagram|tiktok|whatsapp|telegram/.test(joined)) return true;
    // leet spellings of the long app names (short ones like `ig` stay whole-word only: `1g` must not become `ig`)
    if (SOCIAL_SKELETON_RE.test(foldCatName(text))) return true;
    const tokens = tokensOf(text);
    for (let i = 0; i < tokens.length; i += 1) {
        const f = foldCatName(tokens[i]);
        if (f.length >= 4 && SOCIAL_SET[f]) return true;
    }
    return false;
}

function hasPhone(text: string): boolean {
    // 7 or more digits once spaces, dashes, dots, brackets and plus signs are removed
    const squeezed = text.replace(/[\s\-.()+\/]/g, '');
    if (/\d{7,}/.test(squeezed)) return true;
    // look-alike letters inside a digit run (`86l234567`, `8612O4567`): only when the run is mostly digits
    const looks = squeezed.replace(/[oO]/g, '0').replace(/[lIi|]/g, '1');
    const m = looks.match(/[0-9]{7,}/g);
    if (m) {
        for (let i = 0; i < m.length; i += 1) {
            const at = looks.indexOf(m[i]);
            const raw = squeezed.slice(at, at + m[i].length);
            if (raw.replace(/[^0-9]/g, '').length >= 5) return true;
        }
    }
    // spelled digits: 5 or more in a row (digits may mix in)
    const words = text
        .toLowerCase()
        .normalize('NFD')
        .replace(/[\u0300-\u036F]/g, '')
        .split(/[\s,.\-]+/);
    let run = 0;
    for (let i = 0; i < words.length; i += 1) {
        const w = words[i];
        if (!w) continue;
        if (SPELLED_DIGITS[w] || /^\d$/.test(w)) {
            run += 1;
            if (run >= 5) return true;
        } else run = 0;
    }
    return false;
}

function hasAddress(text: string): boolean {
    for (let i = 0; i < ADDRESS_RES.length; i += 1) if (ADDRESS_RES[i].test(text)) return true;
    return false;
}

function hasProbe(text: string): boolean {
    const skeleton = foldCatName(text);
    for (let i = 0; i < PROBES.length; i += 1) if (skeleton.indexOf(PROBES[i]) !== -1) return true;
    // "asl" (age/sex/location) as a word
    const words = wordsOf(text).map(foldCatName);
    for (let i = 0; i < words.length; i += 1) if (words[i] === 'asl' || words[i] === 'age') return true;
    return false;
}

/**
 * Checks one free-text message. `{ok: true, text}` is the normalised text to store and deliver; `{ok: false, why}`
 * names the reason class (`empty` and `long` are the length errors). Never throws.
 */
export function filterChatText(input: unknown, options: ChatFilterOptions = {}): ChatFilterResult {
    if (typeof input !== 'string') return { ok: false, why: 'empty' };
    if (input.length > CHAT_LIMITS.rawMax) return { ok: false, why: 'long' };
    const text = normalizeChatText(input);
    if (!text) return { ok: false, why: 'empty' };
    if (codePoints(text) > CHAT_LIMITS.textMax) return { ok: false, why: 'long' };
    if (!ALLOWED_RE.test(text)) return { ok: false, why: 'charset' };
    if (hasWords(text)) return { ok: false, why: 'words' };
    if (hasEmailOrHandle(text) || hasEmailOrHandle(collapseSpaced(text))) return { ok: false, why: 'contact' };
    if (hasLink(text)) return { ok: false, why: 'link' };
    if (hasPhone(text) || hasAddress(text)) return { ok: false, why: 'contact' };
    if (options.probes && hasProbe(text)) return { ok: false, why: 'contact' };
    return { ok: true, text };
}
